package main

import (
    "fmt"
    "os"
    "os/exec"
)

// Get the file list of the current directory.
func main() {
    // Get the current working directory
    cwd, err := os.Getwd()
    if err != nil {
        fmt.Println("Error getting current working directory:", err)
        return
    }

    // Get the file list of the current directory
    cmd := exec.Command("ls", "-l", cwd)
    err = cmd.Run()
    if err != nil {
        fmt.Println("Error getting file list:", err)
        return
    }

    // Print the file list
    fmt.Println("File list:")
    for _, file := range strings.Split(string(cmd.Output), "\n") {
        fmt.Println(file)
    }
